local M = class("SimulateLiftMainView",LikeOO.OOPopBase)
-- 侠客人生模拟器
M.m_uiName = "SimulateLift/SimulateLiftMain"  -- prefab name
M.m_size_type = 1
M.m_iphoneXAdapter = true
--版本1 普通模拟器 版本2是古剑联动
local Ui_Path = {
    { 
        npc1 = "simulateLift/a_hd_jhmnq_zjm_lh1",
        npc2 = "simulateLift/a_hd_jhmnq_zjm_lh",
        title_img = "zh_cn/a_hd_jhmnq_zjm_bt",
    },
    {
        npc1 = "simulateLift/a_hd_thym_zjm_tyc",
        npc2 = "simulateLift/a_hd_thym_zjm_whsd",
        title_img = "zh_cn/a_thym_bt",
    },
}

function M:onEnter()
    self:bindUI()
    self:refreshUI()

    self.m_control:setOnceTimer(0.5,function()
        if not self.m_control:activityOverExamine(self.m_model.m_data) then
            RedPointUtil:saveLocalRedPointFreshTime("simulate_everyDayRedDot")
        end
    end)
end

function M:showCloud(callBack)
    local fivelinesOpenAnim = ResourceUtil:LoadUIGameObject("FivelinesNew/FivelinesOpenAnim", Vector3.zero, nil)
    fivelinesOpenAnim.transform:SetParent(self.m_rootView.transform, false)
    self.m_control:setOnceTimer(1.5, function() 
        UIUtil.destroyObject(fivelinesOpenAnim)
        if callBack then
            callBack()
        end
    end)
end

function M:refreshUI()
    self:refreshImgByVsn()
    self:setTextByLanKey("text_infoText", "tid#ReopenDes_5", self.m_model.m_surplusCount)
    self:refreshActivityTimer()
    local isShowRedDot = UserDataManager:getRedDotByKey("life_reset")
    self:setObjectVisible("img_redDot", isShowRedDot == 1)
    self:setObjectVisible("btn_tokenBtn", self.m_model.m_open_id ~= 319) -- 版本2是古剑联动，隐藏战令入口
end

function M:refreshImgByVsn()
    local ui_index = self.m_model.m_open_id == 285 and 1 or 2
    local ui_tab = Ui_Path[ui_index] or {}
    for i, v in pairs(ui_tab) do
        local game_obj = self:findGameObject(i)
        GameUtil:updateResourcesImg(game_obj, "Texture/" .. v)
    end
    self:setTextByLanKey("little_title_text", self.m_model.m_open_id == 285 and  "simulateLeft_text_0066" or "simulateLeft_text_0067")
end

function M:bindUI()
    self:setTextByLanKey("text_rinseCardText", "simulateLeft_text_0002")
    self:setTextByLanKey("text_outcomeText", "simulateLeft_text_0003")
    self:setTextByLanKey("text_content1", "tid#ReopenDes_1")
    self:setTextByLanKey("text_content2", "tid#ReopenDes_2")
    self:setTextByLanKey("text_content3", "tid#ReopenDes_3")
    self:setTextByLanKey("text_hintText", "tid#ReopenDes_4")
    self:setTextByLanKey("close_title_text", UserDataManager.m_activity_name)
    --self:setTextByLanKey("close_title_text", self.m_model.m_open_id == 285 and "simulateLeft_text_0030" or "simulateLeft_text_0068")
end

function M:refreshActivityTimer()
    local activityData = UserDataManager:getActivesDataByOpenId(self.m_model.m_open_id)
    local startTimer = activityData.start_ts
    local endTimer = activityData.end_ts
    local starT = TimeUtil.gmTime(startTimer)
    local endT = TimeUtil.gmTime(endTimer)
    local timerFormat = Language:getTextByKey("castingSword_str_0012", starT.year, starT.month, starT.day,
            endT.year, endT.month, endT.day)
    self:setTextByLanKey("text_timer", "castingSword_str_0011",timerFormat)
end

function M:destroy()
    
    M.super.destroy(self)
end

return M
